#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.12"
# dependencies = ["pyyaml"]
# ///
"""Generate the edge relay allowlist from modePublic* routers."""

import re
import sys
from pathlib import Path

import yaml

SOURCE = Path("stacks/proxyguard/data/traefik/config")
OUTPUT = Path("stacks/edge/traefik/config/relay.yaml")

TEMPLATE = """\
# GENERATED by scripts/hooks/generate-edge-config.py — do not edit.
# Hostnames of modePublic* routers in {source}/.
http:
  routers:
    relay-public:
      entryPoints: [websecure]
      rule: {rule}
      service: gateway
"""

EMPTY = """\
# GENERATED by scripts/hooks/generate-edge-config.py — do not edit.
# No modePublic* routers in {source}/ — nothing is relayed.
"""


def public_hosts() -> list[str]:
    hosts: set[str] = set()
    for path in sorted(SOURCE.glob("*.yaml")):
        data = yaml.safe_load(path.read_text()) or {}
        for router in ((data.get("http") or {}).get("routers") or {}).values():
            middlewares = (router or {}).get("middlewares") or []
            if any(str(m).startswith("modePublic") for m in middlewares):
                hosts.update(re.findall(r"Host\(`([^`]+)`\)", router.get("rule", "")))
    return sorted(hosts)


def main() -> int:
    write = sys.argv[1:] == ["--write"]
    if sys.argv[1:] and not write:
        print(
            f"{Path(__file__)}:1: usage: generate-edge-config.py [--write] [EDGE002]",
            file=sys.stderr,
        )
        return 2
    hosts = public_hosts()
    if hosts:
        rule = " || ".join(f"Host(`{h}`)" for h in hosts)
        content = TEMPLATE.format(source=SOURCE, rule=rule)
    else:
        content = EMPTY.format(source=SOURCE)
    if OUTPUT.exists() and OUTPUT.read_text() == content:
        return 0
    if write:
        OUTPUT.write_text(content)
        print(f"{OUTPUT}: regenerated — review and stage it")
        return 0
    print(f"{OUTPUT}:1: generated allowlist is stale; run `just edge-config` [EDGE001]")
    return 1


if __name__ == "__main__":
    sys.exit(main())
